import{_ as s,c as t,o as n,j as e,a as l}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"坎上坎下 坎：","description":"京氏易傳 - 坎上坎下 坎：","frontmatter":{"title":"坎上坎下 坎：","description":"京氏易傳 - 坎上坎下 坎："},"headers":[],"relativePath":"classics/jingshi/018.md","filePath":"classics/jingshi/018.md"}'),i={name:"classics/jingshi/018.md"};function r(c,a,o,p,d,m){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"坎上坎下-坎",tabindex:"-1"},[l("坎上坎下 坎： "),e("a",{class:"header-anchor",href:"#坎上坎下-坎","aria-label":"Permalink to “坎上坎下 坎：”"},"​")],-1),e("p",null,"積陰，以陽處中。柔順，不能履重剛之險。故以剛克柔而履險。而曰陽，是以坎為屬中男。分北方之卦也，與離為飛伏。【戊子水，己巳火。】世立宗廟，居於陰位。比近九五，全於坎道，遠於禍害。三公居應，亦為陰暗。成坎之德，在於九五、九二也。【內外居坎，陽處中而為坎。主純陰得陽，為明臣得君，而安其居也。一作君得臣，而顯其道也。】",-1),e("p",null,"建起戊寅至癸未，【大暑至大雪。】積算起癸未至壬午，週而復始。【金水入卦本同宮，氣候起算時日歲月吉凶。】",-1),e("p",null,"五星從位起太白，【太白金星入水宮。】牛宿從位降戊子。【二十八宿，從位八卦，週而復始。】歲候運數三十六。【配六位，分陰陽；三百五十六，（虎易注：疑為三百六十五之誤。）餘日四分之一。分五行，配運氣，吉凶見矣。】",-1),e("p",null,"內外俱坎，是重剛之位。《易》曰：“坎，陷也。”【坎水能深陷於物；處坎之險，不可不習。故曰：習坎。便習之習後，可得履於險而不陷沒者。不以剛履柔，不能成坎之道也。】",-1),e("p",null,"震以陽居初，能震動於物，能為動主。【乾生震，一陽居於初，震為長男。】坎以陽居中，為重剛之主，故以坎為險。陽變陰，成於陰道。今以陰變陽，止於為節。【次入於節卦。】",-1)])])}const f=s(i,[["render",r]]);export{_ as __pageData,f as default};
